/**
 * #4875 on the REAL database: the merchant's receipt, stored in
 * `merchant_receipts` the way `insertMerchantReceiptOnce` stores it, reaches
 * the accounting entry `buildAccountingEntryForPayment` builds — its stated
 * lines and VAT, and how its total compares with the amount Haven settled.
 *
 * The receipt is the demo merchant's own (`fixtures/merchant-receipts`),
 * generated by its `generateInvoice`.
 */
import { randomUUID } from 'node:crypto'
import { beforeAll, beforeEach, expect, it } from 'vitest'
import db from '../../../db.js'
import { describeDb, initDbHarness, resetDb } from '../../../infra/__tests__/helpers/db-harness.js'
import { insertMerchantReceiptOnce } from '../../../infra/repositories/machine-payments.js'
import { buildAccountingEntryForPayment } from '../entry.js'
import se25 from './fixtures/merchant-receipts/demo-merchant-se25.json' with { type: 'json' }

const CHAIN = 84532
const TOKEN = '0x036cbd53842c5426634e7929541ec2318f3dcf7e'
const PAYER = '0x00000000000000000000000000000000000000f1'
const MERCHANT = '0x00000000000000000000000000000000000000aa'
const RESOURCE = 'https://demo-merchant.example/x402/buy_storage'

let seq = 0

async function seedSettled(amountHuman: string): Promise<{ userId: string; intentId: string; evidenceId: string }> {
  const user = await db.query<{ id: string }>(
    `INSERT INTO users (email, password_hash) VALUES ($1, 'x') RETURNING id`,
    [`receipt-statement-${++seq}-${Date.now()}@test.example`],
  )
  const userId = user.rows[0].id
  const agent = await db.query<{ id: string }>(
    `INSERT INTO agents (user_id, name) VALUES ($1, 'receipt agent') RETURNING id`,
    [userId],
  )
  const agentId = agent.rows[0].id
  const intentId = randomUUID()
  const amountRaw = String(Math.round(Number(amountHuman) * 1_000_000))
  const txHash = `0x${String(++seq).padStart(64, 'a')}`.slice(0, 66)
  await db.query(
    `INSERT INTO payment_intents
       (id, agent_id, user_id, account_address, chain_id, token_symbol, token_address, to_address,
        amount_raw, amount_human, delegate_address, allowance_nonce, sign_hash, status, tx_hash,
        confirmed_at, expires_at, source, payment_rail, execution_rail,
        machine_metadata, x402_resource_url, payment_resource_url, merchant_address,
        x402_merchant_address, delegation_hash, created_at)
     VALUES ($1, $2, $3, $4, ${CHAIN}, 'USDC', $5, $6,
             $7, $8, '0x00000000000000000000000000000000000000d1', 0, $9,
             'confirmed', $10, NOW(), NOW() + interval '10 minutes', 'x402', 'x402', 'erc7710',
             '{"settlement_scheme":"erc7710"}'::jsonb, $11, $11, $6, $6, $12, NOW())`,
    [
      intentId, agentId, userId, PAYER, TOKEN, MERCHANT, amountRaw, amountHuman,
      `0x${String(++seq).padStart(64, 'b')}`.slice(0, 66),
      txHash, RESOURCE,
      `0x${String(++seq).padStart(64, 'c')}`.slice(0, 66),
    ],
  )
  const evidence = await db.query<{ id: string }>(
    `INSERT INTO machine_payment_evidence
       (payment_intent_id, agent_id, user_id, rail, proof_status, tx_hash, chain_id,
        resource_url, payer_address, settlement_address, token_symbol, token_address,
        amount_raw, amount_human, confirmed_at, amount_sek, fx_rates)
     VALUES ($1, $2, $3, 'x402', 'payment_confirmed', $4, ${CHAIN},
             $5, $6, $7, 'USDC', $8, $9, $10, NOW(), '0.0052', '{"SEK":10.42}'::jsonb)
     RETURNING id`,
    [intentId, agentId, userId, txHash, RESOURCE, PAYER, MERCHANT, TOKEN, amountRaw, amountHuman],
  )
  return { userId, intentId, evidenceId: evidence.rows[0].id }
}

describeDb('the merchant receipt statement on the accounting entry (#4875)', () => {
  beforeAll(initDbHarness)
  beforeEach(resetDb)

  it('a stored receipt with lines reaches the entry, and its total matches what Haven settled', async () => {
    const { userId, intentId, evidenceId } = await seedSettled('0.0005')
    expect(await insertMerchantReceiptOnce(evidenceId, null, JSON.stringify(se25))).toBe(true)

    const entry = await buildAccountingEntryForPayment(userId, intentId)
    expect(entry).not.toBeNull()
    expect(entry!.receiptStatement).toMatchObject({
      currency: 'USDC',
      merchantVatTreatment: 'SE_25',
      totals: { exclVat: '0.0004', vatPercent: 25, vatAmount: '0.0001', inclVat: '0.0005' },
      totalCheck: 'matches',
    })
    expect(entry!.receiptStatement!.lines).toHaveLength(1)
    expect(entry!.receiptStatement!.lines[0].description).toBe(se25.rader[0].beskrivning)
  })

  it('a receipt whose total differs says so, and the booked amount stays the settled one', async () => {
    const { userId, intentId, evidenceId } = await seedSettled('0.001')
    await insertMerchantReceiptOnce(evidenceId, null, JSON.stringify(se25))

    const entry = await buildAccountingEntryForPayment(userId, intentId)
    expect(entry!.receiptStatement!.totalCheck).toBe('differs')
    expect(entry!.amountHuman).toBe('0.001')
    expect(entry!.amountAtomic).toBe('1000')
  })

  it('a receipt with no lines, and no receipt at all, are "not stated"', async () => {
    const withoutLines = await seedSettled('0.0005')
    const { rader: _rader, ...noLines } = se25
    await insertMerchantReceiptOnce(withoutLines.evidenceId, null, JSON.stringify(noLines))
    expect((await buildAccountingEntryForPayment(withoutLines.userId, withoutLines.intentId))!.receiptStatement).toBeNull()

    const noReceipt = await seedSettled('0.0005')
    expect((await buildAccountingEntryForPayment(noReceipt.userId, noReceipt.intentId))!.receiptStatement).toBeNull()
  })
})
